CREATE OR REPLACE PROCEDURE public.sp_update_event(IN p_id uuid, IN p_tenant_id uuid, IN p_title character varying, IN p_description text, IN p_event_type_id uuid, IN p_event_date date, IN p_start_time time without time zone, IN p_end_time time without time zone, IN p_location character varying, IN p_organizer_id uuid, IN p_status character varying, IN p_scope character varying, IN p_branch_id uuid, IN p_is_organization_wide boolean, IN p_photo_urls text[], IN p_updated_at timestamp with time zone)  LANGUAGE plpgsql AS $procedure$ BEGIN     UPDATE events      SET title = p_title, description = p_description, event_type_id = p_event_type_id,          event_date = p_event_date, start_time = p_start_time, end_time = p_end_time,          location = p_location, organizer_id = p_organizer_id, status = p_status,          scope = p_scope, branch_id = p_branch_id, is_organization_wide = p_is_organization_wide,          photo_urls = p_photo_urls, updated_at = p_updated_at     WHERE id = p_id AND tenant_id = p_tenant_id; END; $procedure$ ;
